2344:     fn check_add_bases_txn(
2345:         &mut self,
2346:         other_transaction: &Transaction,
2347:         other_version: u64,
2348:     ) -> Result<()> {
2349:         if let Operation::UpdateBases { new_bases } = &self.transaction.operation {
2350:             match &other_transaction.operation {
2351:                 Operation::UpdateBases {
2352:                     new_bases: committed_bases,
2353:                 } => {
2354:                     // Check if any of the bases being added conflict with committed bases
2355:                     for new_base in new_bases {
2356:                         for committed_base in committed_bases {
2357:                             // Check for ID conflicts (if both have non-zero IDs)
2358:                             if new_base.id != 0
2359:                                 && committed_base.id != 0
2360:                                 && new_base.id == committed_base.id
2361:                             {
2362:                                 return Err(self
2363:                                     .incompatible_conflict_err(other_transaction, other_version));
2364:                             }
2365:                             // Check for name conflicts
2366:                             if new_base.name == committed_base.name && new_base.name.is_some() {
2367:                                 return Err(self
2368:                                     .incompatible_conflict_err(other_transaction, other_version));
2369:                             }
2370:                             // Check for path conflicts
2371:                             if new_base.path == committed_base.path {
2372:                                 return Err(self
2373:                                     .incompatible_conflict_err(other_transaction, other_version));
2374:                             }
2375:                         }
2376:                     }
2377:                     Ok(())
2378:                 }
2379:                 // UpdateBases doesn't conflict with data operations
2380:                 _ => Ok(()),
2381:             }
2382:         } else {
