2218:                         id, entry.uuid
2219:                     ))
2220:                 })?;
2221:                 let path = base_path.extract_path(registry.clone())?;
2222:                 let dir = if base_path.is_dataset_root {
2223:                     path.join(crate::dataset::INDICES_DIR)
2224:                 } else {
2225:                     path
2226:                 };
2227:                 // Foreign bases are opened with default store params:
2228:                 // per-base source credentials are not plumbed through the
2229:                 // clone commit path. Documented limitation shared with deep
2230:                 // clone's base reads (see
2231:                 // <https://github.com/lance-format/lance/issues/6093>).
2232:                 let (store, _) = ObjectStore::from_uri_and_params(
2233:                     registry,
2234:                     &base_path.path,
2235:                     &Default::default(),
2236:                 )
2237:                 .await?;
2238:                 (Some(store), dir)
2239:             }
2240:         };
2241:         let path = indices_dir
2242:             .join(entry.uuid.to_string())
2243:             .join(file.path.as_str());
2244:         let store = store.as_deref().unwrap_or(source_store);
2245:         store
2246:             .open(&path)
2247:             .await?
2248:             .get_range(file.offset as usize..end)
