2254:     // Full ledger validation before interpreting anything; reader semantics
2255:     // skip unknown mappings, and a writer must not relocate a history it
2256:     // cannot fully interpret.
2257:     let ledger = decode_frag_reuse_ledger_from_content(entry.index_version, &content).await?;
2258:     if ledger.has_unsupported_transitions() {
2259:         return Err(Error::not_supported(
2260:             "the fragment reuse history contains mappings this writer cannot relocate; \
2261:              upgrade to a newer version of Lance before cloning this table",
2262:         ));
2263:     }
2264: 
2265:     let relocated =
2266:         relocate_stable_partition_bases(&content, |base_id| match (&base_remap, base_id) {
2267:             // Deep clone materializes every referenced map into the clone's
2268:             // own `_fri/`, so every stamp clears to unset.
2269:             (CloneBaseRemap::Deep, _) => Ok(None),
2270:             // The source's own base gets the id the clone assigned to it.
