2277:                     Ok(Some(id))
2278:                 } else {
2279:                     Err(Error::corrupt_file_named(
2280:                         "FRI details",
2281:                         format!("stable partition mapping references missing base {id}"),
2282:                     ))
2283:                 }
2284:             }
2285:         })?;
