2289:     let index_id = Uuid::new_v4();
2290:     let target_indices_dir = target_base.clone().join(crate::dataset::INDICES_DIR);
2291:     let spilled = (relocated.len() > FRAG_REUSE_INLINE_DETAILS_LIMIT).then(|| {
