2301:         IndexMetadata {
2302:             uuid: index_id,
2303:             name: entry.name.clone(),
2304:             fields: entry.fields.clone(),
2305:             covering_fields: entry.covering_fields.clone(),
2306:             dataset_version: entry.dataset_version,
2307:             fragment_bitmap: entry.fragment_bitmap.clone(),
2308:             index_details: Some(Arc::new(prost_types::Any {
2309:                 type_url: "/lance.table.FragmentReuseIndexDetails".into(),
2310:                 value: details_value,
2311:             })),
2312:             index_version: entry.index_version,
2313:             created_at: entry.created_at,
2314:             // The relocated entry lives in the clone.
2315:             base_id: None,
2316:             files: entry.files.clone(),
2317:         },
2318:         spilled,
2319:     ))
2320: }
