423: async fn do_commit_new_dataset(
424:     object_store: &ObjectStore,
425:     source_store: Option<&ObjectStore>,
426:     commit_handler: &Arc<dyn CommitHandler>,
427:     base_path: &Path,
428:     uri: &str,
429:     transaction: &Transaction,
430:     write_config: &ManifestWriteConfig,
431:     manifest_naming_scheme: ManifestNamingScheme,
432:     metadata_cache: &DSMetadataCache,
433:     session: Arc<Session>,
434: ) -> Result<(Manifest, ManifestLocation)> {
435:     let pb_transaction = pb::Transaction::try_from(transaction)?;
436:     let inline_transaction = pb_transaction.encoded_len() <= MAX_INLINE_TRANSACTION_BYTES;
437:     // Classified from the operation itself. Reading it back off the inline
438:     // copy would tie the verdict to the payload size instead.
439:     let may_change_schema = operation_may_change_schema(&pb_transaction);
440: 
441:     // Files a shallow clone writes into the target before the manifest
442:     // commit; deleted again when the commit conclusively fails.
443:     let mut spilled_clone_files: Vec<Path> = Vec::new();
444:     let clone_source = if let Operation::Clone {
445:         is_shallow,
446:         ref_version,
447:         ref_path,
448:         ..
449:     } = &transaction.operation
450:     {
451:         // The source manifest must be read through the source store, which may differ
452:         // from the destination store when cloning across object stores/accounts. Falls
453:         // back to the destination store for same-store clones.
454:         let source_store = source_store.unwrap_or(object_store);
455:         let source_base_path =
456:             ObjectStore::extract_path_from_uri(session.store_registry(), ref_path.as_str())?;
457:         let source_manifest_location = commit_handler
458:             .resolve_version_location(&source_base_path, *ref_version, &source_store.inner)
459:             .await?;
460:         let source_manifest = Dataset::load_manifest(
461:             source_store,
462:             &source_manifest_location,
463:             ref_path.as_str(),
464:             &session,
465:         )
466:         .await?;
467:         ensure_can_write_manifest(&source_manifest)?;
468: 
469:         // Prepare the cloned index metadata now: an uncloneable tagged FRI
