344:     /// A synchronous map covering exactly `addrs`, so an existing synchronous
345:     /// remap step runs unchanged over one unit of work. `Sync` borrows its
346:     /// map; `Batch` translates `addrs` (deduplicated) and builds a map of
347:     /// that size, released with the returned value: memory is O(one unit),
348:     /// never O(source rows).
349:     pub async fn resolve(
350:         &self,
351:         addrs: impl IntoIterator<Item = u64>,
352:     ) -> Result<Cow<'a, RowAddrRemap>> {
353:         match self {
354:             Self::Sync(remap) => Ok(Cow::Borrowed(remap)),
355:             Self::Batch(remapper) => {
356:                 let mut addrs: Vec<u64> = addrs.into_iter().collect();
357:                 addrs.sort_unstable();
358:                 addrs.dedup();
359:                 let translated = remap_row_ids_async(*remapper, &addrs).await?;
360:                 let map: HashMap<u64, Option<u64>> = addrs.into_iter().zip(translated).collect();
361:                 Ok(Cow::Owned(RowAddrRemap::direct(map)))
362:             }

486: fn plan_tagged_remap(
487:     ledger: &FragReuseLedger,
488:     provenance: &RoaringBitmap,
489:     live: &RoaringBitmap,
490:     lineage: &RoaringBitmap,
491: ) -> TaggedRemapPlan {
492:     let mut coverage = provenance.clone();
493:     let mut admitted = provenance.clone();
494:     let mut hops: Vec<PlannedHop> = Vec::new();
495:     let mut applied = vec![false; ledger.transitions().len()];
496:     let mut changed = false;
497:     // Set once a stable-partition hop is applied: from then on the segment's
498:     // stored addresses are being moved, and no partial hop may be skipped.
499:     let mut restamped = false;
500:     // Transitions are in lineage order (producers before consumers), so one
501:     // pass reaches a fixpoint.
502:     for (position, transition) in ledger.transitions().iter().enumerate() {
503:         let sources: RoaringBitmap = transition
504:             .sources()
505:             .iter()
506:             .map(|digest| digest.id as u32)
507:             .collect();
508:         let overlap = &sources & &coverage;
509:         if overlap.is_empty() {
510:             continue;
511:         }
512:         if overlap == sources {
513:             coverage -= &sources;
514:             let destinations: RoaringBitmap = transition
515:                 .destinations()
516:                 .iter()
517:                 .map(|digest| digest.id as u32)
518:                 .collect();
519:             coverage |= &destinations;
520:             admitted |= &destinations;
521:             hops.push(match transition.mapping() {
522:                 Mapping::OrderedCompaction(remap) => PlannedHop::Compaction(remap.as_ref().clone()),
523:                 // Fully covered: the segment owns every source of this
524:                 // transition, so its entering fragment set is exactly the
525:                 // sources (the free / restamp case).
526:                 Mapping::StablePartition(_) => {
527:                     restamped = true;
528:                     PlannedHop::StablePartition {
529:                         position,
530:                         enter_fragments: overlap.clone(),
531:                     }
532:                 }
533:             });
534:             applied[position] = true;
535:         } else {
536:             match transition.mapping() {
537:                 // The v0 straddle fallback is only sound while the segment's
538:                 // stored addresses are untouched.
539:                 Mapping::OrderedCompaction(_) if !restamped => {
540:                     coverage -= &overlap;
541:                 }
542:                 // A partially covered stable partition cannot be restamped,
543:                 // and a partial hop of any kind after a restamp would publish
544:                 // a file whose addresses depend on a mapping its bitmap no
545:                 // longer pins: skip the segment cleanly and let a rebuild
546:                 // catch it up.
547:                 Mapping::OrderedCompaction(_) | Mapping::StablePartition(_) => {
548:                     return TaggedRemapPlan::Blocked {
549:                         fragment: overlap.min().unwrap(),
550:                     };
551:                 }
552:             }
553:         }
554:         changed = true;
555:     }
556:     // Iron law: any destination fragment the final bitmap claims comes from
557:     // an applied (fully-covered) hop or was directly covered to begin with.
558:     debug_assert!(
559:         ledger
560:             .transitions()
561:             .iter()
562:             .enumerate()
563:             .all(|(position, transition)| {
564:                 applied[position]
565:                     || transition.destinations().iter().all(|digest| {
566:                         !coverage.contains(digest.id as u32)
567:                             || provenance.contains(digest.id as u32)
568:                     })
569:             }),
570:         "a remapped fragment bitmap may only claim destinations the segment fully owns"
571:     );
572:     for fragment in (&coverage - live).iter() {
573:         let mentioned = ledger.transitions().iter().any(|transition| {
574:             transition
575:                 .sources()
576:                 .iter()
577:                 .chain(transition.destinations())
578:                 .any(|digest| digest.id as u32 == fragment)
579:         });
580:         if lineage.contains(fragment) && !mentioned {
581:             return TaggedRemapPlan::Blocked { fragment };
582:         }
583:     }
584:     if !changed {
585:         TaggedRemapPlan::Identity
586:     } else {
587:         TaggedRemapPlan::Remap {
588:             hops,
589:             coverage,
590:             admitted,
591:         }
592:     }
593: }
