595: /// The fragments a segment's FILE still addresses, recovered from its
596: /// stored bitmap.
597: ///
598: /// Under the v0 reuse index a deferred compaction left an index file holding
599: /// SOURCE addresses while `load_all_indices` swapped the segment's stored
600: /// `fragment_bitmap` to the group's DESTINATIONS and the next commit
601: /// persisted that swap; the v0 remap planner compensates with its
602: /// `data_predates_version` rule (`index.dataset_version <
603: /// version.dataset_version` means the data still needs the group). A tagged
604: /// table lifts the v0 bytes verbatim and treats the stored bitmap as
626: fn effective_provenance(
627:     ledger: &FragReuseLedger,
628:     stored: &RoaringBitmap,
629:     segment_dataset_version: u64,
630: ) -> RoaringBitmap {
631:     let mut bitmap = stored.clone();
632:     for transition in ledger.transitions().iter().rev() {
633:         let Some(legacy_version) = transition.legacy_dataset_version() else {
634:             continue;
635:         };
636:         // The legacy watermark is the version immediately before the rewrite
637:         // committed (#9620), so a segment stamped at it still predates the
638:         // compaction and holds source addresses: the boundary is inclusive,
639:         // as in the v0 remap (`data_predates_version`) and cleanup rules.
640:         if segment_dataset_version > legacy_version {
641:             continue;
642:         }
643:         let destinations: RoaringBitmap = transition
644:             .destinations()
645:             .iter()
646:             .map(|digest| digest.id as u32)
647:             .collect();
648:         let sources: RoaringBitmap = transition
649:             .sources()
650:             .iter()
651:             .map(|digest| digest.id as u32)
652:             .collect();
653:         if destinations.is_empty()
654:             || !destinations.is_subset(&bitmap)
655:             || !(&sources & &bitmap).is_empty()
656:         {
657:             continue;
658:         }
659:         bitmap -= &destinations;
660:         bitmap |= &sources;
661:     }
662:     bitmap
663: }
