355: pub(crate) async fn derive_superseded_segments(
356:     dataset: &Dataset,
357: ) -> lance_core::Result<Vec<IndexMetadata>> {
358:     let stored = read_manifest_indexes(
359:         &dataset.object_store,
360:         &dataset.manifest_location,
361:         &dataset.manifest,
362:     )
363:     .await?;
364:     // The coverage derivation below flows through `load_indices`, the lenient
365:     // reader path: a segment whose coverage crosses an unsupported transition
366:     // (or an unknown envelope record) gets an empty translated bitmap, so its
367:     // valid coverage shrinks and the subset check could prune a segment a
368:     // newer client still serves. Validate the ledger strictly first, exactly
369:     // as `derive_tagged_trim` does. Living here (not in the caller's retry
370:     // loop) makes the refusal hold on every rebased re-derivation too.
371:     if let Some(entry) = stored
372:         .iter()
373:         .find(|idx| idx.name == FRAG_REUSE_INDEX_NAME && idx.index_version != 0)
374:     {
375:         let content = load_raw_frag_reuse_content(dataset, entry).await?;
376:         let ledger = decode_frag_reuse_ledger_from_content(entry.index_version, &content).await?;
377:         if ledger.has_unsupported_transitions() {
378:             return Err(Error::not_supported(
379:                 "the tagged FRI history carries transitions this client cannot interpret; \
380:                  upgrade to a newer version of Lance before pruning superseded index segments",
381:             ));
382:         }
383:     }
384:     // The reader's own coverage derivation (translated through the ledger,
385:     // direct-coverage-wins applied); not reimplemented here.
386:     use crate::index::DatasetIndexExt;
387:     let derived = dataset.load_indices().await?;
388:     let derived_by_uuid: HashMap<uuid::Uuid, &RoaringBitmap> = derived
389:         .iter()
390:         .filter_map(|idx| {
391:             idx.fragment_bitmap
392:                 .as_ref()
393:                 .map(|bitmap| (idx.uuid, bitmap))
394:         })
395:         .collect();
396:     let live = dataset.fragment_bitmap.as_ref();
397: 
398:     let mut groups: HashMap<&str, Vec<&IndexMetadata>> = HashMap::new();
399:     for index in stored.iter() {
400:         if is_system_index(index) {
401:             continue;
402:         }
403:         groups.entry(index.name.as_str()).or_default().push(index);
404:     }
405: 
406:     let mut removals = Vec::new();
407:     for segments in groups.into_values() {
408:         let mut segments = segments;
409:         // Newest first; uuid as a stable tie-break.
410:         segments.sort_by(|a, b| {
411:             b.dataset_version
412:                 .cmp(&a.dataset_version)
413:                 .then_with(|| b.uuid.cmp(&a.uuid))
414:         });
415:         let mut kept_direct = RoaringBitmap::new();
416:         let mut kept_any = false;
417:         for segment in segments {
418:             // A segment this build cannot serve (unknown type or newer index
419:             // version) is opaque: its translated coverage is invisible, so it
420:             // is never pruned, and it must not mask anyone -- the reader will
421:             // not answer queries from it, so its bitmap covers nothing.
422:             if !crate::index::index_is_usable(segment) {
423:                 kept_any = true;
424:                 continue;
425:             }
426:             let Some(stored_bitmap) = segment.fragment_bitmap.as_ref() else {
427:                 // Unknown coverage cannot be reasoned about; always keep.
428:                 kept_any = true;
429:                 continue;
430:             };
431:             let direct_live = stored_bitmap & live;
432:             let mut valid = direct_live;
433:             if let Some(translated) = derived_by_uuid.get(&segment.uuid) {
434:                 valid |= *translated & live;
435:             }
436:             if kept_any && valid.is_subset(&kept_direct) {
437:                 removals.push(segment.clone());
438:             } else {
439:                 kept_any = true;
440:                 kept_direct |= stored_bitmap & live;
441:             }
442:         }
443:     }
444:     Ok(removals)
445: }
