636:     let mut running = 0usize;
637:     for &count in partition_counts.iter() {
638:         cursors.push(running);
639:         running += count as usize;
640:     }
641: 
642:     let mut interleave_indices = vec![(0usize, 0usize); total_rows];
643:     for (batch_idx, col) in part_id_columns.iter().enumerate() {
644:         for (row_idx, &part_id) in col.values().iter().enumerate() {
645:             let cursor = &mut cursors[part_id as usize];
646:             interleave_indices[*cursor] = (batch_idx, row_idx);
647:             *cursor += 1;
648:         }
649:     }
650: 
651:     Ok((interleave_indices, partition_counts))
652: }
