388: fn strip_row_preserving_wrappers(plan: &Arc<dyn ExecutionPlan>) -> Option<&FilteredReadExec> {
389:     let mut current: &dyn ExecutionPlan = plan.as_ref();
390:     loop {
391:         if let Some(filtered_read) = current.downcast_ref::<FilteredReadExec>() {
392:             return Some(filtered_read);
393:         }
394:         if let Some(proj) = current.downcast_ref::<ProjectionExec>() {
395:             // Empty projections qualify: DataFusion uses one when a `COUNT(*)`'s
396:             // argument no longer needs any columns.
397:             let input_schema = proj.input().schema();
398:             let identity = proj.expr().iter().all(|projection_expr| {
399:                 projection_expr
400:                     .expr
401:                     .downcast_ref::<Column>()
402:                     .is_some_and(|c| c.name() == input_schema.field(c.index()).name())
403:             });
404:             if !identity {
405:                 return None;
406:             }
407:         }
408:         if current.fetch().is_some()
409:             || !matches!(current.cardinality_effect(), CardinalityEffect::Equal)
410:         {
411:             return None;
412:         }
413:         let [input] = current.children()[..] else {
414:             return None;
415:         };
416:         current = input.as_ref();
417:     }

